from typing import List, Tuple

def max_aggregate(stdata: List[Tuple[str, int]]) -> Tuple[str, int]:
    aggregate_dict = {}
    for name, score in stdata:
        if name in aggregate_dict:
            aggregate_dict[name] += score
        else:
            aggregate_dict[name] = score
    return max(aggregate_dict.items(), key=lambda x: x[1])

